{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name IN ('loadgenerator','ts-ui-dashboard') AND span_name LIKE '%routeservice/routes%' AND attr_span_kind IN ('Client','Server') GROUP BY ALL ORDER BY 1,3,4",
          "claim": "Every /api/v1/routeservice/routes request through ts-ui-dashboard takes about 3000 ms and returns 502 to the load generator."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, metric, attr_source, attr_destination, count(*) n, round(sum(value),0) total FROM (SELECT 'abn' p,* FROM abnormal_metrics_sum UNION ALL SELECT 'nor',* FROM normal_metrics_sum) WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ui-dashboard%' AND attr_destination LIKE '%ts-route-service%' GROUP BY ALL ORDER BY p",
          "claim": "TCP flag events on the ts-ui-dashboard to ts-route-service connection rise from 371 to 2425 while other dashboard connections stay near normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, count(*) n FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'nor',* FROM normal_traces) WHERE service_name='ts-route-service' AND span_name='GET /api/v1/routeservice/routes' AND attr_span_kind='Server' GROUP BY ALL ORDER BY p",
          "claim": "ts-route-service handles only 1 /routes request in the abnormal window versus 449 in the normal window, so requests never arrive."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n, min(time) first_t FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND level='ERROR' AND message LIKE '%dial tcp 10.108.144.64:8080: i/o timeout%' GROUP BY ALL",
          "claim": "ts-ui-dashboard logs repeated 'dial tcp 10.108.144.64:8080: i/o timeout' errors on /api/v1/routeservice/routes with status 502."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name IN ('loadgenerator','ts-ui-dashboard') AND span_name LIKE '%routeservice/routes%' AND attr_span_kind IN ('Client','Server') GROUP BY ALL ORDER BY 1,3,4",
          "claim": "The route-service failure surfaces at the user-facing dashboard as 3 s server spans and 502 responses to the load generator."
        }
      ]
    }
  ]
}
